def overlap_minutes(meetings: list[list[int]], k: int) -> int:
    delta = {}
    for s, e in meetings:
        if s == e:
            continue
        delta[s] = delta.get(s, 0) + 1
        delta[e] = delta.get(e, 0) - 1
    times = sorted(delta)
    active = 0
    total = 0
    prev = None
    for t in times:
        if prev is not None and active >= k:
            total += t - prev
        active += delta[t]
        prev = t
    return total
